(() => {
 const form=document.querySelector('.seo-calculator');if(!form)return;form.noValidate=true;
 const drawings={sector:'<rect x="4" y="7" width="24" height="21" rx="3"/><path d="M11 28V5h10v23"/>',client:'<circle cx="16" cy="16" r="12"/><circle cx="16" cy="16" r="7"/><circle cx="16" cy="16" r="2"/>',traffic:'<path d="M5 4v24h24M12 23V13m7 10V7m7 16V16"/>',size:'<path d="m3 11 13-7 13 7-13 7-13-7Zm0 6 13 7 13-7M3 23l13 7 13-7"/>',level:'<path d="m2 12 14-7 14 7-14 7-14-7Zm6 4v7q8 7 16 0v-7m6-4v12"/>',budget:'<rect x="4" y="7" width="24" height="21" rx="3"/><path d="M4 12h24m-1 6h-7v5h7M7 7V4h17v3"/>',screen:'<rect x="3" y="4" width="26" height="19" rx="2"/><path d="M16 23v6m-7 0h14"/>',shop:'<path d="M2 4h4l4 18h16l4-13H7"/><circle cx="12" cy="28" r="1"/><circle cx="25" cy="28" r="1"/>',service:'<path d="m3 13 7-7 6 2 6-2 7 7-7 14-6-3-6 2-7-13Zm7-7 9 11-4 4-7-7m14-8-6 2"/>',home:'<path d="m3 14 13-11 13 11v15H3V14Zm10 15V19h6v10"/>',rocket:'<path d="M12 20c0-12 10-16 17-17 0 8-5 17-17 17Zm0 0-6 6m3-12H3v10l9-4m6-3v12H8"/>'};
 const icon=id=>`<svg viewBox="0 0 32 32" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${drawings[id]||drawings.sector}</svg>`;
 const steps=[
 {label:'Secteur',key:'sector',icon:'sector',title:'Dans quel secteur travaillez-vous ?',options:[['Logiciel & tech','screen'],['E-commerce','shop'],['Services aux entreprises','service'],['Artisanat & proximité','home'],['Autre activité','rocket']]},
 {label:'Client',key:'value',icon:'client',title:'Quelle est la valeur d’un nouveau client ?',hint:'Montant moyen HT d’une vente ou d’un contrat, en euros.',max:50000,unit:'€'},
 {label:'Trafic',key:'traffic',icon:'traffic',title:'Combien de visites SEO recevez-vous ?',hint:'Visites mensuelles actuelles issues de la recherche naturelle. Utilisez vos données Analytics si disponibles.',max:100000,unit:'/ mois'},
 {label:'Taille',key:'size',icon:'size',title:'Quelle est la taille de votre site ?',hint:'Estimez le nombre de pages utiles à indexer.',options:[['Moins de 100 pages'],['De 100 à 499 pages'],['De 500 à 1 000 pages'],['Plus de 1 000 pages']]},
 {label:'Niveau',key:'level',icon:'level',title:'Quelles ressources SEO avez-vous déjà ?',options:[['Nous débutons en SEO'],['L’équipe dispose des bases'],['Un spécialiste SEO est déjà impliqué']]},
 {label:'Budget',key:'budgetChoice',icon:'budget',title:'Quel budget mensuel voulez-vous envisager ?',hint:'Des enveloppes de simulation, pas les tarifs de l’agence. Le devis dépendra du périmètre.',options:[['500 € / mois'],['1 500 € / mois'],['3 000 € / mois'],['À définir ensemble']]}
 ];
 const state={sector:'',value:0,traffic:0,size:'',level:'',budgetChoice:'',budget:null,contact:2,close:20,low:300,mid:600,high:1000};let step=0;
 const fields=form.querySelector('#calc-fields'),result=form.querySelector('#calc-result'),next=form.querySelector('#calc-next'),prev=form.querySelector('#calc-prev'),stages=form.querySelector('.calc-stages'),error=form.querySelector('.calc-error'),progress=form.querySelector('progress');
 const num=n=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:1}).format(n),eur=n=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function remember(){const checked=fields.querySelector('input[type=radio]:checked');if(checked)state[checked.name]=checked.value;const n=fields.querySelector('input[type=number]');if(n&&n.value!==''&&n.validity.valid)state[n.name]=n.valueAsNumber;}
 function render(focus=false){const s=steps[step];result.hidden=true;fields.hidden=false;next.hidden=false;prev.hidden=step===0;error.textContent='';form.classList.remove('show-results');form.querySelector('#step-label').textContent=`Étape ${step+1} sur 6`;progress.value=step+1;stages.innerHTML=steps.map((x,i)=>`<li class="${i<step?'is-done':''}" ${i===step?'aria-current="step"':''}><span class="stage-icon">${icon(x.icon)}</span><span>${x.label}</span></li>`).join('');next.textContent=step===5?'Voir mes scénarios →':'Suivant →';
 let content=s.hint?`<p class="calc-hint">${s.hint}</p>`:'';
 if(s.options){content+=`<div class="calc-options ${step===0?'sector-options':'list-options'}">`+s.options.map(([label,shape])=>`<label class="calc-option"><input type="radio" name="${s.key}" value="${label}" required ${state[s.key]===label?'checked':''}><span class="choice-content">${shape?icon(shape):''}<span>${label}</span></span></label>`).join('')+'</div>';}
 else{content+=`<div class="slider-answer"><label class="visually-hidden" for="${s.key}">${s.title}</label><input id="${s.key}" name="${s.key}" type="number" min="0" max="${s.max}" step="1" required inputmode="numeric" value="${state[s.key]}"><span>${s.unit}</span></div><label class="visually-hidden" for="${s.key}-range">Ajuster : ${s.title}</label><input class="seo-range" id="${s.key}-range" type="range" min="0" max="${s.max}" step="1" value="${state[s.key]}"><div class="range-limits"><span>0 ${s.unit==='€'?'€':''}</span><span>${num(s.max)} ${s.unit==='€'?'€':''}</span></div>`;}
 fields.innerHTML=`<fieldset><legend tabindex="-1">${s.title}</legend>${content}</fieldset>`;
 const range=fields.querySelector('input[type=range]'),number=fields.querySelector('input[type=number]');if(range){range.addEventListener('input',()=>{number.value=range.value;state[s.key]=Number(range.value)});number.addEventListener('input',()=>{if(number.validity.valid&&number.value!==''){range.value=number.value;state[s.key]=number.valueAsNumber}});}
 if(focus)fields.querySelector('legend').focus({preventScroll:true});}
 function assumption(id,label,max,stepSize=1){return `<label>${label}<input name="${id}" type="number" min="0" max="${max}" step="${stepSize}" value="${state[id]}" required></label>`;}
 function cards(){return [['Bas',state.low],['Intermédiaire',state.mid],['Haut',state.high]].map(([label,gain],i)=>{const leads=gain*state.contact/100,customers=leads*state.close/100,revenue=gain*6.5*state.contact/100*state.close/100*state.value,cost=state.budget===null?null:state.budget*12;return `<article class="scenario-card ${i===1?'scenario-featured':''}">${i===1?'<span class="scenario-badge">Hypothèse centrale</span>':''}<h4>Scénario ${label.toLowerCase()}</h4><strong class="scenario-gain">+${num(gain)}</strong><p>visites mensuelles supplémentaires au mois 12</p><dl><div><dt>Trafic total au mois 12</dt><dd>${num(state.traffic+gain)} / mois</dd></div><div><dt>Contacts supplémentaires au mois 12</dt><dd>${num(leads)} / mois</dd></div><div><dt>Clients supplémentaires au mois 12</dt><dd>${num(customers)} / mois</dd></div><div><dt>CA supplémentaire sur 12 mois</dt><dd>${eur(revenue)}</dd></div><div><dt>Budget annuel comparé</dt><dd>${cost===null?'À définir':eur(cost)}</dd></div></dl><div class="scenario-ratio"><span>Ratio CA supplémentaire / budget</span><strong>${cost>0?'× '+num(revenue/cost):'—'}</strong></div></article>`}).join('');}
 function showResults(){step=6;fields.hidden=true;prev.hidden=true;next.textContent='Modifier mes réponses';form.classList.add('show-results');stages.innerHTML='';progress.value=6;form.querySelector('#step-label').textContent='Votre simulation';result.hidden=false;
 const budgets={'500 € / mois':500,'1 500 € / mois':1500,'3 000 € / mois':3000};state.budget=budgets[state.budgetChoice]??null;
 result.innerHTML=`<h3 class="visually-hidden" tabindex="-1">Vos trois scénarios SEO</h3><div class="scenario-summary">${[state.sector,eur(state.value)+' / client',num(state.traffic)+' visites / mois',state.size,state.level,state.budgetChoice].map((x,i)=>`<span>${icon(steps[i].icon)}${esc(x)}</span>`).join('')}</div><p class="scenario-disclaimer">Trois simulations illustratives, sans probabilité attribuée. Les objectifs de trafic ci-dessous sont des hypothèses modifiables, pas des prévisions issues de votre marché.</p><div class="scenario-grid">${cards()}</div><details class="scenario-assumptions"><summary>Voir et ajuster les hypothèses de calcul</summary><p>Hausse progressive et linéaire du trafic supplémentaire, du mois 1 au mois 12. Le total annuel équivaut à 6,5 fois le gain mensuel final. Les conversions et la valeur client restent constantes. Le secteur, la taille et le niveau servent au cadrage, sans multiplier artificiellement les résultats.</p><div class="assumption-grid">${assumption('low','Gain mensuel final — bas',1000000)}${assumption('mid','Gain mensuel final — intermédiaire',1000000)}${assumption('high','Gain mensuel final — haut',1000000)}${assumption('contact','Visites → contacts (%)',100,.1)}${assumption('close','Contacts → clients (%)',100,.1)}</div><button type="button" id="recalc">Actualiser les scénarios</button><p id="assumption-error" role="alert"></p></details><p class="scenario-footnote">Le chiffre d’affaires n’est pas un bénéfice. Ce ratio n’est pas un ROI net : il exclut la marge et les coûts hors SEO. Aucune durée de rentabilisation ne peut être déduite de ces seules données.${state.value===0?' Avec une valeur client nulle, le chiffre d’affaires calculé reste nul.':''}${state.budget===null?' Sans budget défini, le ratio n’est pas calculé.':''}</p><div class="scenario-cta"><h3>Un scénario à confronter à votre réalité.</h3><p>${state.level==='Nous débutons en SEO'?'Un diagnostic permettra de définir vos premières priorités.':'Nous pouvons examiner votre stratégie et vos ressources existantes.'} ${state.size==='Plus de 1 000 pages'?'Le volume du site justifie notamment un examen de l’indexation et des modèles de pages.':''}</p><a class="local-primary" href="/contact/?besoin=seo">Étudier mon potentiel avec Ecospheare ↗</a></div>`;
 result.querySelector('#recalc').addEventListener('click',()=>{const inputs=[...result.querySelectorAll('input')];for(const el of inputs)if(!el.reportValidity())return;const vals=Object.fromEntries(inputs.map(el=>[el.name,el.valueAsNumber]));const e=result.querySelector('#assumption-error');if(vals.low>vals.mid||vals.mid>vals.high){e.textContent='Le scénario bas doit rester inférieur ou égal à l’intermédiaire, puis au haut.';return;}Object.assign(state,vals);e.textContent='';result.querySelector('.scenario-grid').innerHTML=cards();});result.querySelector('h3').focus({preventScroll:true});}
 prev.addEventListener('click',()=>{remember();if(step>0){step--;render(true)}});
 form.addEventListener('submit',event=>{event.preventDefault();if(step===6){step=0;result.replaceChildren();render(true);return;}if(!form.reportValidity())return;remember();if(step===5)showResults();else{step++;render(true)}});render();
})();
